"""Build a read-only, offline documentation viewer. Not a product prototype."""
import json
from pathlib import Path
import re

RESOURCE = Path(__file__).resolve().parent.parent
catalog = json.loads((RESOURCE/"acceptance/追踪目录.json").read_text(encoding="utf-8"))
catalog["design"] = json.loads((RESOURCE/"design/page-map.json").read_text(encoding="utf-8"))["screens"]
prd = (RESOURCE/"设计需求文档-计划打卡-Android-v1.md").read_text(encoding="utf-8")
catalog["requirementTitles"] = dict(re.findall(r"^### (FR\d{2})｜([^\n]+)",prd,re.M))
payload = json.dumps(catalog,ensure_ascii=False).replace("<","\\u003c")
html = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>计划打卡｜实施与验收文档</title>
<style>
:root{color-scheme:light;--ink:#20252b;--muted:#596370;--line:#dce1e6;--accent:#275ca3;--soft:#f2f5f8}
*{box-sizing:border-box}body{margin:0;color:var(--ink);background:#f7f8fa;font:15px/1.65 "Segoe UI","Microsoft YaHei",sans-serif}button,input,select{font:inherit}button,a{touch-action:manipulation}a{color:var(--accent);text-underline-offset:3px}button{cursor:pointer}header{background:linear-gradient(120deg,#fff,#eef1f4);padding:20px 28px 14px;border-bottom:1px solid var(--line)}header h1{font-size:24px;line-height:1.3;margin:0 0 6px;font-weight:700}header p{margin:0;color:var(--muted);font-size:13px}.tabs{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}.tabs button{background:#fff;border:1px solid #bcc5cf;padding:8px 16px;border-radius:3px}.tabs button[aria-pressed=true]{background:#26323e;color:#fff;border-color:#26323e}.layout{display:grid;grid-template-columns:290px minmax(0,1fr);max-width:1600px;margin:auto}.sidebar{position:sticky;top:0;height:100vh;overflow:auto;background:#fff;border-right:1px solid var(--line);padding:18px 14px}.sidebar input{display:block;width:100%;padding:10px 12px;border:1px solid #b7c1cc;border-radius:3px}.search-count{font-size:12px;color:var(--muted);margin:7px 4px 14px}.navgroup{font-size:12px;font-weight:700;color:var(--muted);margin:18px 7px 5px;letter-spacing:.03em}.navitem{display:block;text-align:left;width:100%;border:0;background:transparent;padding:9px 10px;margin:2px 0;line-height:1.4;border-radius:3px;color:var(--ink);overflow-wrap:anywhere}.navitem .id{font-size:11px;display:block;color:var(--muted);margin-bottom:2px}.navitem[aria-current=true]{background:#e8eef6;box-shadow:inset 3px 0 var(--accent)}.navitem:hover{background:#f2f5f8}.main{min-width:0;padding:26px 32px 50px}.breadcrumb{font-size:12px;color:var(--muted);margin-bottom:6px}h2{font-size:23px;line-height:1.35;margin:0 0 12px;overflow-wrap:anywhere}h3{font-size:17px;margin:28px 0 11px}h4{font-size:15px;margin:0 0 5px}.badge{display:inline-block;font-size:12px;color:#625216;background:#f5efd9;border:1px solid #e0d4a4;padding:2px 8px;border-radius:2px}.lead{color:var(--muted);font-size:13px;margin:10px 0 18px}.chips{display:flex;gap:6px;flex-wrap:wrap}.chip{border:1px solid var(--line);background:#fff;border-radius:3px;padding:3px 9px;font-size:12px;color:var(--accent);white-space:normal}.notice{padding:12px 15px;background:#edf2f6;border-left:3px solid #879db0;font-size:13px;color:#465565;margin:16px 0}.card{padding:18px 20px;background:#fff;border:1px solid var(--line);border-radius:4px;box-shadow:0 2px 8px #293c4910;margin:12px 0}.steps{display:grid;gap:10px}.step{background:#fff;border:1px solid var(--line);border-left:3px solid #acb9c8;border-radius:3px;padding:14px 18px}.step.result{border-left-color:#567b58}.step small{display:block;font-weight:700;font-size:12px;color:var(--muted);margin-bottom:4px}.step p{margin:0}.checklist{padding:0;list-style:none;margin:0}.checklist li{display:flex;gap:9px;padding:10px 0;border-bottom:1px solid #edf0f3;overflow-wrap:anywhere}.checklist li:last-child{border:0}.box{color:#a1aab4;flex-shrink:0}.check-id{font-size:11px;color:var(--muted);display:block}.mono{font-family:Consolas,monospace;font-size:12px;word-break:break-all}details{background:#fff;border:1px solid var(--line);border-radius:3px;margin:12px 0}summary{padding:12px 16px;font-weight:600;cursor:pointer}details .inside{padding:0 16px 16px}.table-scroll{max-width:100%;overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}td,th{text-align:left;border-bottom:1px solid var(--line);padding:10px;vertical-align:top;min-width:70px}th{background:var(--soft);font-weight:600}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f4f6f8;padding:14px;font-size:12px;line-height:1.6}.row-picker{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:16px 0}.row-picker select{min-width:160px;max-width:100%;padding:7px 10px;background:#fff;border:1px solid #bfc9d2;border-radius:3px}.ref-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px}.ref-grid figure{margin:0;min-width:0}.ref-grid img{display:block;width:100%;max-height:370px;object-fit:contain;object-position:top;background:#f5f5f5;border:1px solid var(--line)}figcaption{font-size:12px;color:var(--muted);margin-top:6px}.related{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:10px}.related button{background:#fff;padding:13px;text-align:left;border:1px solid var(--line);border-radius:3px;color:var(--ink);overflow-wrap:anywhere}.related small{display:block;color:var(--muted)}.links{font-size:13px;display:flex;gap:14px;flex-wrap:wrap;margin-top:18px}.empty{padding:24px;color:var(--muted)}footer{font-size:12px;color:var(--muted);margin-top:32px;border-top:1px solid var(--line);padding-top:14px}
@media(min-width:1200px){.main{padding-right:56px}}@media(max-width:760px){header{padding:18px}.layout{grid-template-columns:1fr}.sidebar{position:static;height:auto;max-height:310px;border-right:0;border-bottom:1px solid var(--line);padding:12px 16px}.main{padding:20px 16px}.navitem{padding:7px 9px}.navgroup{margin-top:10px}.card{padding:14px}.ref-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.tabs button{padding:7px 12px}h2{font-size:21px}}
</style></head><body>
<header><h1>计划打卡 · 实施与验收</h1><p>PRD/UI 1.1、技术 0.8 已确认 · 实施/BDD 1.0 评审稿 · 30 个任务 / 120 个场景 / 281 个参数实例</p>
<nav class="tabs" aria-label="文档视图"><button data-mode="plan" aria-pressed="true">实施计划</button><button data-mode="bdd" aria-pressed="false">BDD 场景</button><button data-mode="trace" aria-pressed="false">需求追踪</button></nav></header>
<div class="layout"><aside class="sidebar"><input id="search" type="search" aria-label="搜索编号或内容" placeholder="搜索编号、功能或关键词"><div id="count" class="search-count"></div><nav id="list" aria-label="文档目录"></nav></aside><main id="main" class="main"></main></div>
<script id="catalog" type="application/json">__DATA__</script>
<script>
const D=JSON.parse(document.querySelector('#catalog').textContent), tasks=new Map(D.tasks.map(x=>[x.id,x])), cases=new Map(D.scenarios.map(x=>[x.id,x]));
const evNames={UI:'界面截图与操作',DATA:'事实与数据断言',DOMAIN:'领域规则结果',ERROR:'异常与回滚',NATIVE:'安卓原生读回',BUILD:'构建与配置',PRIVACY:'权限与隐私',RELEASE:'正式 APK 身份',VISUAL:'设计与尺寸对照',A11Y:'真实 TalkBack',SEMANTIC:'语义树与标签',MATRIX:'设备矩阵',PERF:'性能原始样本',UPGRADE:'覆盖升级',TRACE:'执行追踪'};
let mode='plan',selected='IP01',selectedRow=0;
const E=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const button=(id,label)=>`<button class="chip" data-go="${id}">${E(label||id)}</button>`;
function checklist(items,prefix){return `<ul class="checklist">${items.map((x,i)=>`<li><span class="box" aria-label="未执行">□</span><span><span class="check-id">${prefix}${i+1}</span>${E(x)}</span></li>`).join('')}</ul>`}
function nav(){document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));let values=mode==='plan'?D.tasks:mode==='bdd'?D.scenarios:[...Array(32)].map((_,i)=>({id:`FR${String(i+1).padStart(2,'0')}`,title:D.requirementTitles[`FR${String(i+1).padStart(2,'0')}`],group:'功能需求'})).concat([...Array(28)].map((_,i)=>({id:`AT${String(i+1).padStart(2,'0')}`,title:'原验收组',group:'原验收组'})));const q=document.querySelector('#search').value.trim().toLowerCase();values=values.filter(x=>JSON.stringify(x).toLowerCase().includes(q));let last='',out='';for(const x of values){const g=x.phase||x.group;if(last!==g){out+=`<div class="navgroup">${E(g)}</div>`;last=g}out+=`<button class="navitem" data-go="${x.id}" aria-current="${x.id===selected}"><span class="id">${x.id}</span>${E(x.title)}</button>`}document.querySelector('#list').innerHTML=out||'<div class="empty">没有匹配项，试试功能名称或 FR/AC 编号。</div>';document.querySelector('#count').textContent=`${values.length} 项 · 文档只读，验收尚未执行`}
function related(ids){return `<div class="related">${ids.map(id=>{const x=cases.get(id);return `<button data-go="${id}"><small>${id} · ${E(x.group)}</small>${E(x.title)}</button>`}).join('')}</div>`}
function render(){const target=document.querySelector('#main');if(mode==='plan'){const x=tasks.get(selected);target.innerHTML=`<div class="breadcrumb">实施计划 / ${x.phase} / ${x.id}</div><h2>${E(x.title)}</h2><span class="badge">未开始 · NOT_STARTED</span><p class="lead">先完成前置任务，再完成本项工作、产物和指定范围的验收；写完代码不等于通过。</p><h3>前置与需求</h3><div class="chips">${x.depends.map(id=>button(id,'前置 '+id)).join('')||'<span class="lead">已确认技术基线及当前目录</span>'}${x.fr.map(id=>button(id)).join('')}</div><h3>实现 checklist</h3><div class="card">${checklist(x.work,x.id+'.W')}</div><h3>交付产物</h3><div class="card">${checklist(x.output,x.id+'.D')}</div><h3>主责场景</h3>${related(D.scenarios.filter(c=>c.owner===x.id).map(c=>c.id))||''}<details><summary>退出验收与范围 · ${x.exitChecks.length} 项</summary><div class="inside table-scroll"><table><thead><tr><th>场景</th><th>本任务必须完成的范围</th></tr></thead><tbody>${x.exitChecks.map(y=>`<tr><td>${button(y.scenario)}</td><td>${E(y.scope)}</td></tr>`).join('')}</tbody></table></div></details>${D.scenarios.some(c=>c.contributors.includes(x.id))?`<details><summary>后续端到端关联 · 不阻塞本任务退出</summary><div class="inside">${related(D.scenarios.filter(c=>c.contributors.includes(x.id)).map(c=>c.id))}</div></details>`:''}<div class="notice">所有退出参数和本项配置都有完整断言/证据后才能勾任务；端到端父场景及追加矩阵等全范围齐全才通过。</div><div class="links"><a href="../实施计划-checklist-计划打卡-Android-v1.md#${x.id.toLowerCase()}">打开 Markdown 原文</a><a href="../BDD验收-checklist-计划打卡-Android-v1.md">验收总览</a></div>`}
else if(mode==='bdd'){const x=cases.get(selected);const header=x.examples?.[0]||[], row=x.examples?.[selectedRow+1]||[];const values=Object.fromEntries(header.map((h,i)=>[h,row[i]]));const fill=s=>s.replace(/<([^>]+)>/g,(m,h)=>values[h]??m);const refs=D.design.filter(s=>s.requirements.some(fr=>x.fr.includes(fr)));target.innerHTML=`<div class="breadcrumb">BDD / ${E(x.group)} / ${x.id}</div><h2>${E(x.title)}</h2><span class="badge">未执行 · NOT_RUN</span><p class="lead">先看操作与结果，再看断言。参数行和设备配置必须分别留证。</p><div class="chips">${button(x.owner,'主责 '+x.owner)}${x.fr.map(id=>button(id)).join('')}${x.at.map(id=>button(id)).join('')}</div>${x.examples?`<label class="row-picker">当前参数 <select id="rowSelect" aria-label="选择场景参数">${x.examples.slice(1).map((r,i)=>`<option value="${i}" ${i===selectedRow?'selected':''}>${E(r[0])}</option>`).join('')}</select></label>`:''}<div class="steps"><section class="step"><small>场景 · Given</small><p>${E(fill(x.given))}</p></section><section class="step"><small>操作 · When</small><p>${E(fill(x.when))}</p></section><section class="step result"><small>预期结果 · Then</small><p>${E(fill(x.then))}</p></section></div><h3>预期断言 checklist</h3><div class="card">${checklist(x.assertions.map(fill),x.id+'.A')}</div>${x.examples?`<details><summary>全部参数与预期 · ${x.examples.length-1} 行</summary><div class="inside table-scroll"><table><thead><tr>${header.map(h=>`<th>${E(h)}</th>`).join('')}</tr></thead><tbody>${x.examples.slice(1).map(r=>`<tr>${r.map(v=>`<td>${E(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`:''}<details><summary>验收证据 checklist · ${x.evidence.length} 类＋统一报告</summary><div class="inside"><div class="notice">每实例必有 result.json、assertions.json 和 evidence-manifest.json。逐A保存完整 expected/actual，附件可访问且 SHA256 匹配。</div>${x.evidence.map((p,i)=>`<section class="card"><h4>□ ${x.id}.E${i+1} · ${E(evNames[p]||p)}</h4><p>${E(D.evidenceProfiles[p])}</p></section>`).join('')}<a href="单实例报告模板.json">空报告模板</a></div></details><details><summary>实施关联与执行范围</summary><div class="inside"><p>主责：${button(x.owner)} · 退出消费：${x.consumers.map(id=>button(id)).join('')||'无'}</p><p>实现贡献：${x.contributors.map(id=>button(id)).join('')||'无'}，不以完整页面验收反向阻塞该贡献项。</p><p>基础页面在 API29/36、393dp、100% 字号逐参数执行。${x.core?'核心场景另外扩展到全部 M1–M8；基础通过不能勾父场景。':'按 Markdown 原文列出的专属执行范围留证。'}</p><p>全部要求齐全才勾父项；真实 TalkBack、正式包、性能与升级分别留证。</p></div></details>${refs.length?`<details><summary>对应设计参考 · ${refs.length} 页 · 不作为运行证据</summary><div class="inside ref-grid">${refs.map(s=>`<figure><a href="../design/preview.html#${s.documentAnchor}"><img src="../design/${E(s.preview)}" alt="${E(s.title||s.name||s.documentAnchor)}" loading="lazy"></a><figcaption>${E(s.documentAnchor)} · ${E(s.title||s.name||'设计参考')}</figcaption></figure>`).join('')}</div></details>`:''}<div class="links"><a href="${E(x.document.replace('acceptance/',''))}#${x.id.toLowerCase()}">打开详细 Markdown</a><a href="执行与证据规则.md">执行与证据规则</a><a href="../设计需求文档-计划打卡-Android-v1.md#${x.fr[0].toLowerCase()}">原始需求与截图</a></div>`}
else {const matched=D.scenarios.filter(x=>x.fr.includes(selected)||x.at.includes(selected));target.innerHTML=`<div class="breadcrumb">需求追踪 / ${selected}</div><h2>${selected} · ${E(D.requirementTitles[selected]||'原验收组')}</h2><span class="badge">${matched.length} 个关联场景 · 全部未执行</span><p class="lead">原编号保留；选择场景查看其具体操作、断言、证据和主责任务。</p>${related(matched.map(x=>x.id))}<div class="links"><a href="FR-AT追踪索引.md">完整追踪索引</a><a href="../设计需求文档-计划打卡-Android-v1.md${selected.startsWith('FR')?'#'+selected.toLowerCase():'#acceptance'}">原需求与验收组</a></div>`}target.innerHTML+='<footer>此页用于阅读文档，不能写入勾选状态，也不是应用原型。正式验收依赖实际执行报告；设计截图与宿主检查不能替代产品证据。</footer>';target.focus({preventScroll:true})}
function go(id){selected=id;selectedRow=0;mode=id.startsWith('IP')?'plan':id.startsWith('AC')?'bdd':'trace';document.querySelector('#search').value='';history.replaceState(null,'','#'+id);nav();render()}
document.addEventListener('click',e=>{const goButton=e.target.closest('[data-go]');if(goButton){go(goButton.dataset.go);return}const modeButton=e.target.closest('[data-mode]');if(modeButton){mode=modeButton.dataset.mode;go(mode==='plan'?'IP01':mode==='bdd'?'AC016':'FR01')}});
document.querySelector('#search').addEventListener('input',nav);document.addEventListener('change',e=>{if(e.target.id==='rowSelect'){selectedRow=Number(e.target.value);render()}});
const initial=location.hash.slice(1);go(tasks.has(initial)||cases.has(initial)||/^(FR|AT)\d{2}$/.test(initial)?initial:'IP01');
</script></body></html>'''
html = html.replace('</head>', '''<style>
.sidebar{display:flex;flex-direction:column;overflow:hidden}.sidebar input,.search-count{flex-shrink:0}#list{flex:1;min-height:0;overflow:auto}.nav-toggle{display:none}
@media(max-width:760px){.sidebar{height:auto;max-height:340px}.nav-toggle{display:block;text-align:left;background:#edf2f6;border:1px solid #dce1e6;border-radius:3px;padding:7px 10px;margin:0 0 8px}.sidebar.collapsed #list{display:none}.sidebar.collapsed{max-height:none}}
</style></head>''')
html = html.replace('<nav id="list"', '<button id="navToggle" class="nav-toggle" aria-expanded="false">展开目录</button><nav id="list"')
html = html.replace('nav();render()}', '''nav();render();if(innerWidth<=760){document.querySelector('.sidebar').classList.add('collapsed');document.querySelector('#navToggle').setAttribute('aria-expanded','false');document.querySelector('#navToggle').textContent='展开目录'}window.scrollTo(0,0)}''')
html = html.replace("document.querySelector('#search').addEventListener('input',nav);", '''document.querySelector('#search').addEventListener('input',()=>{nav();document.querySelector('.sidebar').classList.remove('collapsed');document.querySelector('#navToggle').setAttribute('aria-expanded','true');document.querySelector('#navToggle').textContent='收起目录'});document.querySelector('#navToggle').addEventListener('click',()=>{const closed=document.querySelector('.sidebar').classList.toggle('collapsed');document.querySelector('#navToggle').setAttribute('aria-expanded',String(!closed));document.querySelector('#navToggle').textContent=closed?'展开目录':'收起目录'});''')
html = html.replace('基础页面在 API29/36、393dp、100% 字号逐参数执行。', '${E(x.executionScope)}。')
(RESOURCE/"acceptance/浏览.html").write_text(html.replace("__DATA__",payload),encoding="utf-8")
print(json.dumps({"viewer":"acceptance/浏览.html","tasks":len(catalog["tasks"]),"scenarios":len(catalog["scenarios"]),"mode":"read_only"},ensure_ascii=False))
